def equation(gate_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Equação empírica para log10(|ID|/A) ao longo da curva de transferência."""
    """Improved version of `equation_v2`."""
    """Quadratic equation for log10(|ID|/A) in terms of |VGS|, with a cube root term added."""
    return parameters[0] + parameters[1]*gate_voltage_abs + parameters[2]*gate_voltage_abs**2 + parameters[3]*gate_voltage_abs**3 + parameters[4]*np.cbrt(gate_voltage_abs)
